import React, { useState, useEffect } from 'react';

const Hero = () => {
  const [displayText, setDisplayText] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCircle, setShowCircle] = useState(true);
  const [showButton, setShowButton] = useState(false);

  const fullText = "You wake up in an unknown place, trapped in this strange world.";

  // 圓圈退去效果
  useEffect(() => {
    const timer = setTimeout(() => {
      setShowCircle(false);
    }, 2000);

    return () => clearTimeout(timer);
  }, []);

  // 打字效果
  useEffect(() => {
    if (!showCircle) {
      const timer = setTimeout(() => {
        if (currentIndex < fullText.length) {
          setDisplayText(prev => prev + fullText[currentIndex]);
          setCurrentIndex(prev => prev + 1);
        } else {
          setTimeout(() => {
            setShowButton(true);
          }, 2000);
        }
      }, 100);

      return () => clearTimeout(timer);
    }
  }, [currentIndex, fullText.length, showCircle]);

  const handleButtonClick = () => {
    // 可以添加其他功能，比如顯示更多信息或重新開始動畫
    console.log('Button clicked!');
  };

  return (
    <section id="hero" className="min-h-screen flex items-center justify-center bg-black relative overflow-hidden">
      {/* 黑色圓圈退去效果 */}
      {showCircle && (
        <div className="absolute inset-0 bg-black flex items-center justify-center">
          <div className="w-96 h-96 bg-black rounded-full animate-circle-shrink"></div>
        </div>
      )}

      {/* 文字內容 */}
      {!showCircle && (
        <div className="relative z-10 text-center text-white px-6 max-w-4xl mx-auto">
          {/* 打字效果文字 */}
          <div className="mb-8">
            <h1 className="text-3xl md:text-5xl font-bold mb-4 leading-relaxed">
              <span className="inline-block">
                {displayText}
                <span className="animate-pulse text-white">|</span>
              </span>
            </h1>
          </div>

          {/* 按鈕 */}
          {showButton && (
            <div className="animate-fade-in-up">
              <button 
                className="group relative inline-flex items-center justify-center px-8 py-4 text-lg font-semibold text-black bg-white rounded-full hover:bg-gray-200 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl"
                onClick={handleButtonClick}
              >
                <span className="relative z-10 flex items-center">
                  Continue
                  <svg className="ml-2 w-5 h-5 group-hover:translate-x-1 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                  </svg>
                </span>
              </button>
            </div>
          )}
        </div>
      )}
    </section>
  );
};

export default Hero;
